using System;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace IntConditionalInc;

public class ConditionalIncrement
{
    public static void IncrementAbove(Span<int> data, int threshold)
    {
        int i = 0;

        if (Vector256.IsHardwareAccelerated && data.Length >= Vector256<int>.Count)
        {
            var thresholdVec = Vector256.Create(threshold);
            var oneVec = Vector256.Create(1);
            var vectors = MemoryMarshal.Cast<int, Vector256<int>>(data);

            for (int v = 0; v < vectors.Length; v++)
            {
                // GreaterThan returns -1 (all bits set) for elements > threshold, 0 otherwise.
                // -1 & 1 == 1, so we add 1 only where condition is true.
                var mask = Vector256.GreaterThan(vectors[v], thresholdVec);
                vectors[v] += mask & oneVec;
            }

            i = vectors.Length * Vector256<int>.Count;
        }
        else if (Vector128.IsHardwareAccelerated && data.Length >= Vector128<int>.Count)
        {
            var thresholdVec = Vector128.Create(threshold);
            var oneVec = Vector128.Create(1);
            var vectors = MemoryMarshal.Cast<int, Vector128<int>>(data);

            for (int v = 0; v < vectors.Length; v++)
            {
                var mask = Vector128.GreaterThan(vectors[v], thresholdVec);
                vectors[v] += mask & oneVec;
            }

            i = vectors.Length * Vector128<int>.Count;
        }

        // Scalar tail
        for (; i < data.Length; i++)
        {
            if (data[i] > threshold)
                data[i]++;
        }
    }
}

